const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Wuhan city geometry
  const wuhan = ee.Geometry.Point([114.3055, 30.5928]).buffer(50000); // ~50km radius

  // January 1-20, 2020
  const jan_start = '2020-01-01';
  const jan_end = '2020-01-21';
  const col_jan = ee.ImageCollection('COPERNICUS/S5P/TROPOMI_L3_NO2')
    .filterDate(jan_start, jan_end)
    .filterBounds(wuhan);

  const jan_size = col_jan.size().getInfo();
  console.log(`January (1-20): Images found = ${jan_size}`);

  // February 10-25, 2020
  const feb_start = '2020-02-10';
  const feb_end = '2020-02-26';
  const col_feb = ee.ImageCollection('COPERNICUS/S5P/TROPOMI_L3_NO2')
    .filterDate(feb_start, feb_end)
    .filterBounds(wuhan);

  const feb_size = col_feb.size().getInfo();
  console.log(`February (10-25): Images found = ${feb_size}`);

  // Check if collections are empty
  if (jan_size === 0 || feb_size === 0) {
    console.log('No data available for one or both periods.');
    console.log('C1');
    return;
  }

  // Extract NO2 column density (NO2_column_number_density band) and apply QA filtering
  const jan_masked = col_jan
    .map(function(img) {
      const qa = img.select('qa_value');
      return img.select('NO2_column_number_density').updateMask(qa.gte(0.75));
    })
    .mean();

  const feb_masked = col_feb
    .map(function(img) {
      const qa = img.select('qa_value');
      return img.select('NO2_column_number_density').updateMask(qa.gte(0.75));
    })
    .mean();

  // Count valid pixels
  const jan_count = jan_masked
    .reduceRegion(
      ee.Reducer.count(),
      wuhan,
      1000,
      1e9
    )
    .get('NO2_column_number_density')
    .getInfo();

  const feb_count = feb_masked
    .reduceRegion(
      ee.Reducer.count(),
      wuhan,
      1000,
      1e9
    )
    .get('NO2_column_number_density')
    .getInfo();

  console.log(`January valid pixels: ${jan_count}`);
  console.log(`February valid pixels: ${feb_count}`);

  // Check if valid pixels exist
  if (jan_count === 0 || feb_count === 0) {
    console.log('No valid pixels after QA filtering.');
    console.log('C2');
    return;
  }

  // Calculate mean NO2 concentration for each period (convert to μmol/m²)
  const jan_mean = jan_masked
    .reduceRegion(
      ee.Reducer.mean(),
      wuhan,
      1000,
      1e9
    )
    .get('NO2_column_number_density')
    .getInfo();

  const feb_mean = feb_masked
    .reduceRegion(
      ee.Reducer.mean(),
      wuhan,
      1000,
      1e9
    )
    .get('NO2_column_number_density')
    .getInfo();

  console.log(`January 1-20 NO2 mean: ${jan_mean ? (jan_mean * 1e6).toFixed(2) : 'null'} μmol/m²`);
  console.log(`February 10-25 NO2 mean: ${feb_mean ? (feb_mean * 1e6).toFixed(2) : 'null'} μmol/m²`);

  // Validate results
  if (jan_mean === null || feb_mean === null || isNaN(jan_mean) || isNaN(feb_mean)) {
    console.log('Calculation returned invalid values.');
    console.log('C3');
    return;
  }

  // Check if values are in reasonable range (0-500 μmol/m²)
  const jan_umol = jan_mean * 1e6;
  const feb_umol = feb_mean * 1e6;

  if (jan_umol < 0 || jan_umol > 500 || feb_umol < 0 || feb_umol > 500) {
    console.log('NO2 values outside expected range.');
    console.log('C3');
    return;
  }

  // Compare: did NO2 decrease from January to February?
  const decrease = feb_umol < jan_umol;
  const diff = jan_umol - feb_umol;

  console.log(`Difference (Jan - Feb): ${diff.toFixed(2)} μmol/m²`);
  console.log(`NO2 decreased: ${decrease}`);

  if (decrease) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
